PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (   id TEXT PRIMARY KEY,     key_hash TEXT UNIQUE NOT NULL,     recovery_code TEXT,     recovery_used INTEGER DEFAULT 0,     created_at INTEGER NOT NULL   , verify_token TEXT, is_active INTEGER DEFAULT 1, email TEXT);
CREATE TABLE notes (   id TEXT PRIMARY KEY,     user_id TEXT NOT NULL,     title_cipher TEXT NOT NULL,     ciphertext TEXT NOT NULL,     category_cipher TEXT,     tags_cipher TEXT,     revision_count INTEGER DEFAULT 1,     created_at INTEGER NOT NULL,     updated_at INTEGER NOT NULL,     FOREIGN KEY (user_id) REFERENCES users(id) );
CREATE TABLE categories (   id TEXT PRIMARY KEY,     user_id TEXT NOT NULL,     name_cipher TEXT NOT NULL,     created_at INTEGER NOT NULL,     FOREIGN KEY (user_id) REFERENCES users(id) );
CREATE TABLE shares (   id TEXT PRIMARY KEY,     note_id TEXT NOT NULL,     owner_id TEXT NOT NULL,     share_key TEXT UNIQUE NOT NULL,     max_views INTEGER,     current_views INTEGER DEFAULT 0,     expires_at INTEGER,     created_at INTEGER NOT NULL,     FOREIGN KEY (note_id) REFERENCES notes(id),   FOREIGN KEY (owner_id) REFERENCES users(id) );
